const raw = $input.first().json || {};
const body = raw.body || raw;
const headers = raw.headers || {};

// --- Security: webhook authentication ---
// Enforcement happens at the Webhook node itself (Header Auth credential).
// A request only reaches this code if it already passed that check.
// This just records metadata for the audit trail.
const provided = headers['x-onboarding-token'] || headers['X-Onboarding-Token'] || '';
const hasToken = provided !== '';

function pick() {
  for (let i = 0; i < arguments.length; i++) {
    const k = arguments[i];
    if (body[k] !== undefined && body[k] !== null && String(body[k]).trim() !== '') return String(body[k]).trim();
  }
  return '';
}

const emp = {
  fullName: pick('fullName','full_name','name'),
  personalEmail: pick('personalEmail','personal_email','email').toLowerCase(),
  companyEmail: pick('companyEmail','company_email','workEmail').toLowerCase(),
  phone: pick('phone','phoneNumber','phone_number'),
  jobTitle: pick('jobTitle','job_title','title','role'),
  department: pick('department','dept'),
  officeLocation: pick('officeLocation','office_location','location','office'),
  employmentType: pick('employmentType','employment_type','type') || 'Full-time',
  startDate: pick('startDate','start_date','startingDate'),
  manager: pick('manager','managerName','manager_name','reportsTo'),
     managerEmail: pick('managerEmail','manager_email').toLowerCase(),
  team: pick('team','squad'),
  equipment: pick('equipment','equipmentRequirements','equipment_requirements'),
  _security: { hasToken: hasToken, source: headers['user-agent'] || 'unknown' },
  _receivedAt: new Date().toISOString(),
};
return [{ json: emp }];

const e = $('Normalize & Verify Request').first().json;
const errors = [];

// Required fields (STEP 1)
const required = ['fullName','personalEmail','jobTitle','department','startDate','manager'];
for (const f of required) { if (!e[f] || String(e[f]).trim() === '') errors.push('Missing required field: ' + f); }

// Email format
if (e.personalEmail && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e.personalEmail)) errors.push('Invalid personal email format');

// Valid start date: parseable and not in the past
let startOk = false;
if (e.startDate) {
  const d = new Date(e.startDate);
  if (!isNaN(d.getTime())) {
    startOk = true;
    const today = new Date(); today.setHours(0,0,0,0);
    if (d < today) errors.push('Start date is in the past: ' + e.startDate);
  } else { errors.push('Unparseable start date: ' + e.startDate); }
}

// Department mapping (STEP 1)
const deptMap = {
  'engineering':'Engineering','eng':'Engineering','sales':'Sales','marketing':'Marketing',
  'finance':'Finance','hr':'People & HR','people':'People & HR','support':'Customer Support',
  'product':'Product','design':'Design','operations':'Operations','it':'IT'
};
const deptKey = (e.department || '').toLowerCase().trim();
const mappedDept = deptMap[deptKey] || '';
if (e.department && !mappedDept) errors.push('Unknown department (no mapping): ' + e.department);

// Manager assignment (STEP 1)
if (!e.manager) errors.push('No manager assigned');

// Duplicate detection (STEP 1)
const existing = $('Lookup Existing Employees').all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const dupe = existing.some(r => {
  const em = String(r.personalEmail || r['Personal Email'] || r.email || '').toLowerCase();
  return em && em === e.personalEmail;
});
if (dupe) errors.push('Duplicate employee record for ' + e.personalEmail);

const isValid = errors.length === 0;
return [{ json: Object.assign({}, e, {
  department: mappedDept || e.department,
  isValid: isValid,
  validationErrors: errors,
  validationSummary: isValid ? 'PASSED' : errors.join('; '),
  employeeId: (e.personalEmail || 'unknown') + '-' + Date.now(),
}) }];

const e = $('Validate Onboarding Data').first().json;
let ai = {};
try {
  const out = $('AI Onboarding Analysis').first().json;
  const t = out && out.output && out.output[0] && out.output[0].content && out.output[0].content[0] ? out.output[0].content[0].text : null;
  ai = (typeof t === 'string') ? JSON.parse(t) : (t || {});
} catch (err) { ai = {}; }

const plan = {
  employeeId: e.employeeId,
  fullName: e.fullName,
  personalEmail: e.personalEmail,
  companyEmail: e.companyEmail,
  phone: e.phone,
  jobTitle: e.jobTitle,
  department: e.department,
  officeLocation: e.officeLocation,
  employmentType: e.employmentType,
  startDate: e.startDate,
  manager: e.manager,
  managerEmail: e.managerEmail,
  team: e.team,
  equipment: e.equipment,
  onboardingSummary: ai.onboarding_summary || 'Onboarding plan pending AI analysis.',
  welcomeMessage: ai.welcome_message || ('Welcome to the team, ' + (e.fullName || '') + '!'),
  checklist: ai.checklist || [],
  trainingPath: ai.training_path || [],
  equipmentRecommendations: ai.equipment_recommendations || [],
  departmentResources: ai.department_resources || [],
  folderName: 'Onboarding - ' + (e.fullName || 'Unknown') + ' (' + (e.startDate || '') + ')',
  status: 'In Progress',
};
return [{ json: plan }];

const p = $('Build Onboarding Plan').first().json;
const applies = (p.department || '').toLowerCase();
const isTech = ['engineering','product','it','design'].indexOf(applies) !== -1;

// STEP 3 — account creation tasks
const accounts = [
  { category: 'Account', system: 'Google Workspace', task: 'Provision Google Workspace / email account' },
  { category: 'Account', system: 'Slack', task: 'Create Slack account and add to team channels' },
  { category: 'Account', system: 'Microsoft Teams', task: 'Provision Microsoft Teams account' },
  { category: 'Account', system: 'Notion', task: 'Grant Notion workspace access' },
  { category: 'Account', system: 'Jira', task: 'Create Jira account and assign project roles' },
  { category: 'Account', system: 'CRM', task: 'Create CRM account (if customer-facing)' },
  { category: 'Account', system: 'Internal Portal', task: 'Grant internal portal / intranet access' },
];
if (isTech) accounts.push({ category: 'Account', system: 'GitHub', task: 'Create GitHub access and add to org teams' });

// STEP 4 — IT provisioning tasks
const it = [
  { category: 'IT', system: 'Hardware', task: 'Assign laptop: ' + (p.equipment || 'standard kit') },
  { category: 'IT', system: 'Software', task: 'Install standard + role software' },
  { category: 'IT', system: 'VPN', task: 'Provision VPN access' },
  { category: 'IT', system: 'MFA', task: 'Enroll in MFA / hardware key' },
  { category: 'IT', system: 'Email Signature', task: 'Configure company email signature' },
  { category: 'IT', system: 'Security', task: 'Apply security policies / endpoint management' },
  { category: 'IT', system: 'Inventory', task: 'Update device inventory record' },
];

const all = accounts.concat(it);
return all.map(function(t){ return { json: {
  employee: p.fullName,
  email: p.personalEmail,
  department: p.department,
  startDate: p.startDate,
  category: t.category,
  system: t.system,
  task: t.task,
  status: 'Pending',
  createdAt: new Date().toISOString(),
} }; });

