const p = $('Build Onboarding Plan').first().json;
const base = DateTime.fromISO(String(p.startDate || ''));
function addDays(d, n){ return d.plus({ days: n }).toFormat('yyyy-MM-dd'); }
const name = p.fullName || 'there';
const touchpoints = [
  { milestone: 'Day 1',   offset: 0,  type: 'Welcome check-in',            to: p.personalEmail, msg: 'Hi ' + name + ', welcome! How is your first day going? Reach out anytime.' },
  { milestone: 'Week 1',  offset: 7,  type: 'Manager feedback request',    to: 'MANAGER',       msg: 'Please share early feedback on ' + name + ' after their first week.' },
  { milestone: 'Week 2',  offset: 14, type: 'Employee satisfaction survey', to: p.personalEmail, msg: 'Hi ' + name + ', a quick survey: how has your onboarding experience been so far?' },
  { milestone: 'Month 1', offset: 30, type: 'Performance check-in',         to: p.personalEmail, msg: 'Hi ' + name + ', time for your 30-day check-in. Let us schedule a chat.' },
  { milestone: 'Month 3', offset: 90, type: 'Probation review reminder',    to: 'MANAGER',       msg: 'Reminder: 90-day probation review for ' + name + ' is due.' },
];
return touchpoints.map(function(t){ return { json: {
  employee: p.fullName,
  employeeEmail: p.personalEmail,
  manager: p.manager,
  milestone: t.milestone,
  followUpType: t.type,
  recipient: t.to === 'MANAGER' ? 'manager' : 'employee',
  dueDate: base.isValid ? addDays(base, t.offset) : '',
  message: t.msg,
  status: 'Pending',
  createdAt: new Date().toISOString(),
} }; });

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const today = new Date(); today.setHours(23,59,59,999);
const due = rows.filter(function(r){
  if (!r.dueDate || String(r.status).toLowerCase() !== 'pending') return false;
  const d = new Date(r.dueDate);
  return !isNaN(d.getTime()) && d <= today;
});
return due.map(function(r){ return { json: r }; });

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const total = rows.length;
function pct(field, done){ if(!total) return 0; const n = rows.filter(r => String(r[field]||'').toLowerCase() === done).length; return Math.round((n/total)*100); }
const completed = rows.filter(r => String(r.status||'').toLowerCase() === 'completed').length;
const pending = total - completed;

// Average onboarding time (createdAt -> startDate) in days
let sumDays = 0, cnt = 0;
rows.forEach(function(r){ const a = new Date(r.createdAt), b = new Date(r.startDate); if(!isNaN(a)&&!isNaN(b)){ sumDays += Math.abs((b-a)/86400000); cnt++; } });
const avgDays = cnt ? Math.round(sumDays/cnt) : 0;

// Department stats
const byDept = {};
rows.forEach(function(r){ const d = r.department || 'Unknown'; byDept[d] = (byDept[d]||0)+1; });
const deptStats = Object.keys(byDept).map(function(k){ return k + ': ' + byDept[k]; }).join(', ');

return [{ json: {
  reportDate: $now.toFormat('yyyy-MM-dd'),
  employeesOnboarded: total,
  completed: completed,
  pendingTasks: pending,
  itCompletionRate: pct('itStatus','done'),
  hrCompletionRate: pct('documentStatus','done'),
  trainingCompletionRate: pct('trainingStatus','done'),
  accountCompletionRate: pct('accountStatus','done'),
  complianceStatus: pct('managerApproval','approved') + '% approved',
  avgOnboardingDays: avgDays,
  departmentStats: deptStats,
} }];

const raw = $input.first().json || {};
const body = raw.body || raw;

const ALLOWED_FIELDS = ['accountStatus','itStatus','documentStatus','trainingStatus','managerApproval'];
const ALLOWED_VALUES = ['Pending','In Progress','Completed','Approved','Rejected','Blocked'];

const employeeId = String(body.employeeId || '').trim();
const field = String(body.field || '').trim();
const value = String(body.value || '').trim();

const errors = [];
if (!employeeId) errors.push('Missing employeeId');
if (!ALLOWED_FIELDS.includes(field)) errors.push('field must be one of: ' + ALLOWED_FIELDS.join(', '));
if (!ALLOWED_VALUES.includes(value)) errors.push('value must be one of: ' + ALLOWED_VALUES.join(', '));

return [{ json: {
  employeeId,
  field,
  value,
  valid: errors.length === 0,
  errors,
  updatedAt: new Date().toISOString(),
} }];

const e = $json;
const payload = { employeeId: e.employeeId };
payload[e.field] = e.value;
return [{ json: payload }];

